questions.answer:
// counter.js
let count = 0;

export function increment() {
  return ++count;
}

export function reset() {
  count = 0;
}

export function getCount() {
  return count;
}

// app.js
import { increment, reset, getCount } from "./counter.js";

console.log(increment(), increment(), getCount()); // 1 2 2
reset();
console.log(getCount()); // 0

count is not exported, so it is private to counter.js. The functions close over the same module-scoped variable, which is why increment and getCount see the same state. Module state is shared by every importer because a module is evaluated once and cached. If you exported count directly, importers would get a live but read-only binding and could not assign to it.

