// src/app.js
import { add, subtract, multiply } from "./index.js";
console.log(add(2, 3), subtract(5, 2), multiply(2, 3));

questions.answer:
// src/index.js
export { add, subtract, default as multiply } from "./math.js";

// src/app.js
import { add, subtract, multiply } from "./index.js";

console.log(add(2, 3), subtract(5, 2), multiply(2, 3));
// 5 3 6

A default export must be renamed explicitly when re-exported as a named binding: default as multiply. export * from "./math.js" would forward add and subtract but not the default. The barrel keeps the public path stable (./index.js) while the implementation can move. Avoid long barrel chains and cycles; they slow builds and make it harder to see where a binding comes from.

